import sys
from math import isqrt

def main():
    n = int(sys.stdin.read().split()[0])
    sieve = bytearray([1]) * (n + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, isqrt(n) + 1):
        if sieve[i]:
            sieve[i * i::i] = bytearray(len(range(i * i, n + 1, i)))
    for p in range(2, n // 2 + 1):
        if sieve[p] and sieve[n - p]:
            print(p, n - p)
            return

main()

